{
  "_task": {
    "id": "635d5d9d4a1bdefeda8bafb8",
    "type": "fact_extraction",
    "entity_id": "0b58a2af55026cc9db99830f",
    "input_digest": "326f4440d816e324a11c956263b2da78"
  },
  "title": "ReMP: Low-Downtime Runtime Model-Parallelism Reconfiguration for LLM Serving",
  "event_hint": "arXiv paper on runtime reconfiguration of TP/PP topology for LLM serving",
  "problem": "Existing LLM inference systems treat model parallelism topology (Tensor Parallelism TP and Pipeline Parallelism PP) as static configuration. This rigid design cannot adapt to dynamically changing inference workloads. State-of-the-art systems lack online reconfiguration capabilities and can only switch configurations by restarting the service, resulting in several minutes of service interruption, KV cache loss, and prohibitive recomputation overhead.",
  "mechanism": "ReMP decouples model parallelism topology from runtime state through three key techniques: (1) Decoupling topology from state—persisting full model state in CPU shared memory, avoiding full service reconstruction; (2) Two-dimensional KV cache migration—jointly remapping cache blocks across pipeline layer dimension and tensor-parallel KV-head dimension to preserve reusable states; (3) End-to-end online reconfiguration integrated into vLLM v1 executor, worker management, KV cache manager, and communication pipeline.",
  "evidence": [
    {
      "claim": "ReMP topology switches complete within 1-7 seconds for models from 7B to 70B parameters",
      "value": "1-7 seconds",
      "baseline": null,
      "condition": "Models ranging from 7B to 70B parameters; specific workload/hardware conditions not fully specified in visible evidence",
      "source_locator": "Abstract, Section 1 (Introduction)"
    },
    {
      "claim": "ReMP achieves speedups of tens to over 100× compared to restart-based reconfiguration",
      "value": "tens to 100×",
      "baseline": "restart-based reconfiguration",
      "condition": "Several transitions exceed 100×; exact baseline conditions not visible in front evidence",
      "source_locator": "Abstract, Section 1 (Introduction)"
    },
    {
      "claim": "ReMP tested on two 8-GPU platforms: NVIDIA H100 and RTX 5090",
      "value": "8-GPU platforms (H100, RTX 5090)",
      "baseline": null,
      "condition": "Two 8-GPU hardware platforms",
      "source_locator": "Section 1 (Introduction)"
    },
    {
      "claim": "Production traffic analysis reveals stable periodic patterns with substantial disparities across time periods",
      "value": "stable periodic patterns",
      "baseline": null,
      "condition": "Analysis of online traffic data from two major service providers (Infinigence Model Service, Zhejiang Lab Model Service)",
      "source_locator": "Section 1 (Introduction), Figure 1"
    },
    {
      "claim": "ReMP decouples four runtime states from launch-time topology: model weights, KV cache, communication groups, and workers",
      "value": "four decoupled states",
      "baseline": null,
      "condition": "Model weights reloaded via CPU memory, KV cache via 2D layer/head migration, comm groups via prebuilt snapshots, workers via standby/wakeup reuse",
      "source_locator": "Section 3 (System Design), Table 1"
    }
  ],
  "evaluation_context": "ReMP is integrated into vLLM v1 core modules. Experiments conducted on two 8-GPU platforms (NVIDIA H100 and RTX 5090) with models ranging from 7B to 70B parameters including Llama2-70B. Production traffic analysis based on two major service providers (Infinigence and Zhejiang Lab) shows stable daily token usage patterns.",
  "limitations": "Evidence pack covers Abstract, Introduction, and early System Design sections only. Full experimental results (including exact workloads, detailed baseline comparisons, specific speedup measurements with conditions, deployment overheads) are not visible in the front evidence. WAN/network transmission considerations are not addressed; the paper focuses on intra-cluster GPU communication for TP/PP.",
  "project_relevance": "ReMP's KV cache migration mechanism demonstrates state preservation across topology changes, which is relevant for cross-region KV cache migration. The two-dimensional remapping (layer + head) provides a design pattern for state redistribution. However, ReMP operates in intra-cluster GPU context, not WAN. For cross-region scenarios, the WAN RTT/bandwidth costs must be weighed against migration benefits. ReMP's decoupling approach (separating logical state from physical placement) is applicable to remote cache design.",
  "primary_source_resolved": true,
  "quality_score": 65,
  "evidence_gaps": [
    {
      "question": "What are the exact workload conditions, input lengths, output lengths, batch sizes, and baseline restart times for the reported 1-7 second reconfiguration and 10-100× speedup claims?",
      "terms": ["workload", "restart time", "baseline", "batch size", "speedup", "TPOT", "TTFT", "Llama2-70B", "reconfiguration time"]
    },
    {
      "question": "What are the communication overheads and data transfer volumes for KV cache migration during TP/PP topology switches?",
      "terms": ["KV cache migration", "transfer", "communication overhead", "data volume", "P2P", "layer", "head"]
    },
    {
      "question": "What are the detailed TTFT, TPOT, and output throughput improvements under dynamic workload simulation compared to fixed TP1PP8 and TP2PP4 baselines?",
      "terms": ["TTFT", "TPOT", "throughput", "dynamic workload", "TP1PP8", "TP2PP4", "fixed configuration"]
    }
  ],
  "source_notes": [
    "Evidence pack is front-evidence-v2 strategy containing ~27% of full document",
    "Abstract claims 1-7 second topology switches for 7B-70B models with 10-100× speedup",
    "Introduction confirms integration into vLLM v1 and testing on H100/RTX 5090 platforms",
    "Full experimental section with detailed measurements not visible in evidence pack"
  ]
}

